class Solution:
    def getOutlierValue(self, arr: List[int]) -> int:
        S = sum(arr)
        freq = Counter(arr)
        best = None
        for o in arr:
            t = S - o
            if t % 2:
                continue
            m = t // 2
            ok = (freq[m] >= 2) if m == o else (freq[m] >= 1)
            if ok:
                best = o if best is None else max(best, o)
        return best

