class Solution {
public:
    int getOutlierValue(vector<int>& arr) {
        long long S = 0;
        unordered_map<long long, int> freq;
        for (int v : arr) { S += v; freq[v]++; }
        long long best = LLONG_MIN;
        for (int v : arr) {
            long long o = v, t = S - o;
            if (t % 2 != 0) continue;
            long long m = t / 2;
            auto it = freq.find(m);
            bool ok = (m == o) ? (it != freq.end() && it->second >= 2) : (it != freq.end());
            if (ok && o > best) best = o;
        }
        return (int) best;
    }
};

